-- The latest versions' notes, for the "What's new" window (Map/News.lua), from CHANGELOG.md.
-- Generated by tools/changelog/build.py; regenerate rather than edit.

local _, ns = ...

ns.MapChangelog = {
	{ version = "Unreleased", date = "", heads = { [1] = "New", }, items = {
		"|cff6e2c0aChat over the full-screen map|r (the menu's Look tab, and Options): the chat windows stay on show over the map while it's full screen, to keep talking while you look. Off unless you turn it on (a player's request).",
		"|cff6e2c0a/openmap status says what loading costs|r: OpenMap's files, the login, the map's setup and building the map (a player found it added load time: this shows where).",
	} },
	{ version = "v0.7.3-beta", date = "2026-10-22", heads = { [1] = "New", [5] = "Fixed", }, items = {
		"|cff6e2c0aKey bindings|r (the game's Keybindings > OpenMap): Find me, Drop a pin, Pins, Quill, Quest log and the map's menu, each opening the map first if it's closed (players' requests).",
		"|cff6e2c0aThe quill draws on dungeons' maps|r: with a dungeon's map up, what you draw goes on its picture and is kept with that dungeon, not on the world map behind it (a player's request).",
		"|cff6e2c0aOnly places you've found|r (the menu's On the map tab, under Places): dungeon entrances, docks and zeppelin towers once you've explored where they are, flight masters once you've learned them. Off unless you turn it on (a player's request).",
		"|cff6e2c0aTownsfolk from another addon's NPC database|r: an addon with a database in Questie's shape can give it to OpenMap (OpenMapAPI.RegisterTownsfolkProvider, docs/api.md), so townsfolk and rare mobs show without Questie (a player's request).",
		"|cff6e2c0aSmooth zooming at any Take colour out|r: the zones' fast pre-drawn art was only used at the setting's default (10%); at any other, every zone was drawn from its hundreds of pieces and the frame rate dropped as their detail came in. It's now used at every setting.",
		"|cff6e2c0aFull screen stays full screen|r, and the quest log you closed stays closed, the next time the map opens: it went back to the window and the quest log each time (a player's report).",
		"|cff6e2c0aImproves performance|r under Fade icons while zooming no longer stays on show over the menu's other tabs (a player's report).",
		"|cff6e2c0aRiverglades and Zephras Isle show their levels|r on the zone hover (35-45 and 1-12, from the Warcraft Wiki; a player's report).",
	} },
	{ version = "v0.7.2-beta", date = "2026-10-21", heads = { [1] = "Improved", [4] = "Fixed", }, items = {
		"|cff6e2c0aZooming is smoother with unexplored areas darkened|r: greying the land you haven't found cost a lot of frame rate while zooming; it now costs far less.",
		"|cff6e2c0aUnexplored areas for one character only|r: the menu's |cff6e2c0aOnly for this character|r, under Unexplored areas, gives this character its own choice (darkened, hidden or shown); every other character keeps the shared one (a player's request).",
		"|cff6e2c0aFade icons while zooming|r says |cff6e2c0aImproves performance|r under it in the map's menu, so it isn't turned off unawares.",
		"|cff6e2c0aThe map loads the zone you pan or zoom to again|r: with an addon adding map icons (Questie, GatherLite ...), it could stay on the zone you started on, so the zone or continent you'd panned to showed none of their icons until you clicked it (a player's report from 0.6, and ours). Its setting, once Follow the view, is now |cff6e2c0aLoad the zone in view|r (the menu's More tab), saying what it does.",
		"|cff6e2c0aThe map window drags and resizes with Move Any installed but turned off|r: OpenMap asked whether Move Any was on for a character named by your first name alone (WoW Forever gives a first and last name), which the game took as on, and left the window to it (a player's report, with the fix).",
	} },
	{ version = "v0.7.1-beta", date = "2026-10-21", heads = { [1] = "Improved", [5] = "Fixed", }, items = {
		"|cff6e2c0aDarkened unexplored areas look better|r (Unexplored areas: Darken): a |cff6e2c0aDarkening|r slider (the menu's sliders, and Options) sets how dark they are, from a light shade to the full one; unfound land is greyed as well as darkened, so the lighter lines Blizzard paints along zones' borders no longer show bright through it; neighbouring zones you haven't found blend into one another, with no light seams between them, and the painted land between zones (north of the Plaguelands, Gilneas, round Ahn'Qiraj ...) darkens with them.",
		"|cff6e2c0aOther addons' icons fade while you zoom|r (Questie's, RestedXP's ...), out as a zoom starts and back in after it, instead of blinking off and on. |cff6e2c0aFade icons while zooming|r, in the map's menu (the Show tab), turns it off.",
		"|cff6e2c0aThe map window can go partly off the screen|r: drag it up until its title and the bar under it are past the top, for just the map (Options' Reset window brings it back), or past the sides and bottom while some of it stays on.",
		"|cff6e2c0aWith Enhance QoL|r, OpenMap says once in chat to turn off its Mover > World Map: the two both size the map, and its scale goes wrong (a player's finding).",
		"|cff6e2c0aOther addons' icons stay on the map|r (RestedXP's, Nauticus's, Questie's ...): they could flicker and go, as anything that set the map's scale counted as zooming. Now only your own zooming does, and never for more than a moment.",
		"|cff6e2c0aFlight masters you've learned are in colour|r, all of them: OpenMap knew only the ones it had seen you visit since it was installed (and, on a client not in English, none). It now asks the game which you've found.",
		"|cff6e2c0aFishing on the zone hover|r shows: OpenMap looked for your Fishing skill in a way WoW Forever no longer offers, and found none.",
		"|cff6e2c0aZeppelin towers show for the Alliance too|r when Zeppelins is on: they were the Horde's only, though their routes showed for everyone and the goblins' zeppelins take anyone.",
	} },
	{ version = "v0.7.0-beta", date = "2026-10-20", heads = { [1] = "New", [4] = "Improved", [7] = "Fixed", }, items = {
		"|cff6e2c0aFishing on the zone hover|r: if you know Fishing, hovering a zone shows the skill at which every cast there lands (Elwynn Forest 25, Hillsbrad Foothills 150, Stranglethorn Vale 225 ...), green if you have it, yellow if most casts land, red if most get away. With |cff6e2c0aZone levels|r, from the original game's values; WoW Forever's own zones have none yet.",
		"|cff6e2c0aShortest Path Forever from anywhere on the map|r: Shift-click a spot in another zone, on another continent or zoomed right out over the whole world, and its journey is planned there. Its own Shift-click only reached the map underneath (the zone or continent you were last zoomed into).",
		"|cff6e2c0aNeedRoll opens where you click|r: a boss in a dungeon's Bosses tab opens NeedRoll on that boss's loot (Shift-click: where the boss is, on NeedRoll's map of the dungeon), and a quest in the Quests tab opens its page there; the Loot tab's button opens the dungeon's own loot. Dire Maul's, Scarlet Monastery's, Stratholme's and Blackrock Spire's wings open on the right one. Needs NeedRoll's newest version (thanks to its author, mikebvs, for the links).",
		"|cff6e2c0aChoose your map|r: the choice the first time the map opens is in the map window's own frame, with plainer words.",
		"|cff6e2c0aThe map stays open while you talk to an NPC|r (or open a vendor, the bags' windows ...): the windowed map is no longer put away to make room. Escape still closes it; maximized, it behaves as before.",
		"|cff6e2c0aReopen map: Center on player, keep zoom|r (the menu's Reopen map, and Options): the map opens on you at the zoom you closed it at.",
		"|cff6e2c0aIronforge's map shows once you've been there|r, even if you came by the Deeprun Tram and haven't found the land round it yet. With unexplored areas hidden, the city counted as found only once you'd explored the part of Dun Morogh over it; now going into a city finds it too.",
	} },
	{ version = "v0.6.0-beta", date = "2026-10-18", heads = { [1] = "New", [12] = "Improved", [21] = "Fixed", }, items = {
		"|cff6e2c0aResponsive ocean & border|r (Options, and the map's menu): zoomed right out, the world map lies on a sea chart painted by Santiago Reyes (used with his permission), laid out for your window's shape: the sea, compass roses, sea creatures, ships and the frame's corners round it, each in its place whether the window is wide, square or tall. The game's own world map stays in the middle, fading into his sea. Zoom out past the whole world to see all of it; the map pans to its edges and no further. Off unless you turn it on. Its frame is the map's only border now: the parchment border and its setting are gone, so with this off the map has none.",
		"|cff6e2c0aOpenMap in your language|r: German, French, Spanish (Spain and Latin America), Italian, Portuguese (Brazil), Russian, Korean and Chinese (Simplified and Traditional), with the game's own words for things (flight masters, map pins, the quest log ...). Place names were already the game's. What's new's notes stay in English.",
		"|cff6e2c0aYour quests from every zone, at any zoom|r: Blizzard's map shows a zone's quests only once you've zoomed in on that zone; now the quests in your log show across the whole map, in the look of Blizzard's (in progress or ready to turn in, their objectives on hover; click one: it opens in the quest log). The menu's |cff6e2c0aQuests from every zone|r turns them off.",
		"|cff6e2c0aEvery cave underground|r: the caves, mines, tunnels, crypts, dens and dungeon entrances Blizzard drew no map of (about 250 of them; it drew 39) surface as you zoom in on them too, as the game's own minimap draws them inside, lying as they do: Fargodeep's neighbours, Dun Algaz's tunnel, the troll and kobold caves, the ogre mounds, Razorfen Kraul's, Blackfathom's and Onyxia's Lair's entrances, and WoW Forever's own new caves and vaults.",
		"|cff6e2c0aTen more gaps painted|r: the blank land between zones is painted by hand by Santiago Reyes (used with his permission) round Tanaris and Silithus, the Plaguelands, Stonetalon and the Barrens, Silverpine and Hillsbrad, Thousand Needles and Feralas, Winterspring and Darkshore, Ashenvale and Azshara, Stranglethorn and the Blasted Lands, Thousand Needles and Dustwallow Marsh, and Desolace and Feralas. Their coasts are his own coastlines, fading out into the sea. Khaz Modan's comes back sharper, from his full-size painting. Options' |cff6e2c0aFilled gaps|r turns them all off.",
		"|cff6e2c0aMap pins into chat|r: Shift-click a pin (on the map or in the Pins list) to put it in chat, as Blizzard's map pin link where the game takes one (whoever clicks it gets the waypoint), with its note; else its note, zone and position as text.",
		"|cff6e2c0aClearing map pins|r: the Pins list's |cff6e2c0aClear|r deletes every pin (it asks first), and Alt-click deletes one at once, on the map or in the list.",
		"|cff6e2c0aHiding your map pins|r: right-click |cff6e2c0aPins|r (in the OpenMap menu, or its button on the map) and your pins leave the map, the button greyed while they're away; right-click again for them back. The Pins list still has them all, and dropping a new pin brings them back.",
		"|cff6e2c0aMailboxes|r in the menu's Townsfolk (from Questie's list of them, as its own map shows them).",
		"|cff6e2c0aIcon size|r (the menu's sliders, and Options): OpenMap's icons on the map bigger or smaller.",
		"|cff6e2c0aCredits|r (What's new's |cff6e2c0aCredits|r button): who has made OpenMap, Santiago Reyes's painted maps, Ironship's and C-Clymer's work on the code, Blizzard's art, the libraries, and everyone who reports problems and ideas.",
		"|cff6e2c0aSmoother zooming with Questie|r: other addons' map icons (Questie's, TomTom's ...) rest while the map zooms and come back as soon as it stops. Each was laid out again on every frame of a zoom, which with Questie's hundreds cost a lot of frame rate. Options' |cff6e2c0aOther addons' icons rest while zooming|r keeps them up.",
		"|cff6e2c0aIn combat, fewer \"action blocked\" errors|r from the map's own icons: the super-trackable ones (quests, points of interest) wait out combat to set their clicks, as the rest already did, and addons loaded later are covered too. Other addons' icons lifted over the map (Leatrix Maps', Azeroth Tripview's, Books on Map Forever's) are lifted as combat ends, not during it. |cff6e2c0aRareScanner's|r rare icons show over the map (they were under its art). A map addon with a HereBeDragons OpenMap can't take over is said once in chat, not passed over. Thanks to Ironship.",
		"|cff6e2c0aQuestie's icons across the view|r: zoomed out over a zone, the quests of every zone in view show, not only those of the zone underneath and the next one.",
		"|cff6e2c0aShortest Path Forever works on the map|r: Shift-click the map to plan a journey (OpenMap's click-to-zoom took every click first).",
		"|cff6e2c0aThe map opens no further in than the deepest zoom|r: centred on you in a city, it opened as far in as the city's map fits (up to half again past the setting, and blurry past the art's own pixels).",
		"|cff6e2c0aThe menu's buttons on the map come off with Shift-right-click|r only, not a plain right-click.",
		"|cff6e2c0aFor other addons|r: OpenMapAPI.CursorPosition() (API version 3), the point under the cursor; with MapAt, the zone under it at any zoom, so a zone-hover tooltip (Zonewise's) can keep working zoomed in, where the map underneath is the zone, not the continent.",
		"|cff6e2c0aThe Pins list|r can be dragged anywhere and stays where you put it. Sharing every pin is one |cff6e2c0aShare all|r button with a menu (as a code, to your group, to your guild), so sending them all to your guild is never one stray click.",
		"|cff6e2c0aThe minimap's detail over Orgrimmar and Thunder Bluff|r as over the other major cities (up to half strength; it was held to 15% there, which hardly showed). |cff6e2c0aMinimap detail in major cities|r (the menu's Up close, and Options) turns it off over all six.",
		"|cff6e2c0aWith a controller (the game's Gamepad UI), OpenMap leaves the world map to Blizzard.|r Closing the map with B said \"OpenMap has been blocked from an action only available to the Blizzard UI\" (and Disable on that message could crash the game). The Gamepad UI sets the controller's buttons again on every map change, and on OpenMap's map those changes run as OpenMap's code, which the game then blocks from closing the map. Until OpenMap can work with the Gamepad UI without that, it says so once in chat and stays out of the map while the Gamepad UI is on; swap to mouse and keyboard and OpenMap's map is back.",
		"|cff6e2c0aThe minimap's detail follows unexplored areas.|r Zooming in, it drew over land you haven't explored as it is: on Hide, Moonglade, the land round Ironforge or Hillsbrad looked explored straight away; on Darken, the unexplored parts of zones you've been to came up undarkened. Up close, unexplored land is now blank parchment (Hide) or darkened (Darken), the minimap's detail with it, as from further out; on Hide a cave under it stays underground.",
		"|cff6e2c0aSantiago Reyes's coastline round Silithus and Ahn'Qiraj.|r His painting leaves its sea clear, and past his coast, where the game's own map has land, the map's blank paper showed through: an orange band down Silithus's and Ahn'Qiraj's west coast in place of his shallows. His shallows and the ink line he draws off the shore show now, there and round every painted gap's coast.",
		"|cff6e2c0aSantiago Reyes's mountains south of Hyjal at full strength.|r Between Felwood, Ashenvale and Azshara, his painting of the land below Mount Hyjal looked washed out, its mountains faint ghosts on blank paper up to a straight line under Hyjal's map. The zones' blank parchment from the sheet he painted on had been left over his finished painting there; it shows now as he painted it.",
		"|cff6e2c0aCaves come up at the usual deepest zoom.|r A cave's map surfaced only once it nearly filled the view, which at the default deepest zoom (48x, where a mine is a speck) most never could: clicking a dungeon entrance glided in and stopped short of it. Over a cave the zoom now goes on past the deepest setting until its map fills the window, and a cave comes up as it fills a quarter of it.",
		"|cff6e2c0aBlizzard's cave maps show their whole cave.|r Their outlines were traced from the maps' pale floors and lost darker rooms and passages' ends: Night Web's Hollow's great chamber, Burning Blade Coven's west loop, Ban'ethil Barrow Den's lower tunnel and more. They're traced now from where the caves' own rooms lie in the game, leaving out only the page's title ribbon and corner knots.",
		"|cff6e2c0aThe map window resizes by its corners again.|r OpenMap put the window back to its saved size in the middle of a drag; now the drag sizes it, the map staying where it is on screen as more or less of it comes into the window, and the drop lays it out at that same scale, with no jump.",
		"|cff6e2c0aTownsfolk without Questie|r: they come from Questie's database, so without Questie the menu says so instead of offering switches that showed nothing, and turning one on says so once in chat.",
		"|cff6e2c0aZones' edges against the sea and the painted gaps.|r A zone's own map is drawn whole to its frame on land, so its coasts and mountains no longer fade out early into an orange band of blank land (Arathi's east coast) or a grey smudge of sea (Arathi's mountains above the Wetlands); where it paints the sea up to its frame, the sea fades in from the frame instead of stopping in a straight line (Eastern Plaguelands' east coast). Mountain strokes mistaken for a printed name no longer cut holes in a zone's map (the brown blot at Thoradin's Wall), and past its own land a zone gives way to Santiago Reyes's painted gaps where they reach.",
		"|cff6e2c0aIronforge's map whole up close.|r The Mystic Ward, the Forlorn Cavern, the Hall of Explorers and the Gates were faded out into the mountain: the city's map faded out in a round from its middle, and Ironforge's wards reach right out to its frame. It's cut to the city instead, as the Undercity's is, with Dun Morogh's mountain round it.",
		"|cff6e2c0aIronforge's minimap detail up close.|r Zooming in on Stormwind brings in the game's minimap; on Ironforge only the painted map showed: the game's minimap there, outside, is the mountain over the city, so OpenMap kept it off. Now the game's own minimap of the city inside (what your minimap shows walking through it) comes in over Ironforge's map as you zoom in, as the minimap does over Stormwind; the Undercity's too.",
		"|cff6e2c0aThe Wetlands' Excavation Site stays hidden until you've found it.|r With Unexplored areas on Hide, the painted mountains south of Whelgar's Excavation Site showed WoW Forever's new valley there (green, with paths and a lake) before you'd been anywhere near it. It's blank parchment now until you've explored Whelgar's Excavation Site or Angerfang Encampment, the parts of the Wetlands' map over it (the game itself keeps no record of exploring the valley), close up too; on Darken it's darkened until then.",
		"|cff6e2c0aFade while moving|r faded for a moment and then came back: the game's own map fade (held off while OpenMap's runs) kept setting the map back to full on every frame you moved. OpenMap's fade now stays.",
		"|cff6e2c0aMap size|r in the map's menu ran away as you dragged it: it scales the window the menu is in, so the slider moved under the cursor. The size now changes when you let go.",
		"The continents' names lost their glow each time you zoomed and flickered back on: they keep it now (the seas' names still rest theirs while the map moves, which keeps zooming smooth).",
		"Blizzard's quest areas trailed the map as you zoomed and sprang back when you stopped: each is now drawn where the map is at that step.",
		"|cff6e2c0aQuests from every zone|r follow the map's own |cff6e2c0aQuest Objectives|r switch: with it off, OpenMap's quest icons go too, as Blizzard's do.",
		"The menu's |cff6e2c0aMinimap button|r row has its icon (it showed none: the icon it named isn't in the game).",
	} },
}
